# parse_client conserva cada argumento en *_raw, aplica strip a los campos requeridos,
# deja None y agrega un error cuando están vacíos, y usa safe_int para edad.

def safe_int(campo: str, valor: str) -> tuple[bool, int | None, str | None]:
    texto = valor.strip()
    if texto == "":
        return False, None, f"ERROR en '{campo}': valor vacío"
    try:
        return True, int(texto), None
    except ValueError:
        return False, None, f"ERROR en '{campo}': no se pudo convertir {valor!r} a int"


def parse_client(nombres, apellido_paterno, apellido_materno, contacto, direccion, edad=None):
    errors = []
    rec = {
        "nombres_raw": nombres,
        "apellido_paterno_raw": apellido_paterno,
        "apellido_materno_raw": apellido_materno,
        "contacto_raw": contacto,
        "direccion_raw": direccion,
        "edad_raw": edad,
        "nombres": None,
        "apellido_paterno": None,
        "apellido_materno": None,
        "contacto": None,
        "direccion": None,
        "edad": None,
        "errors": errors,
    }
    campos = {
        "nombres": nombres,
        "apellido_paterno": apellido_paterno,
        "apellido_materno": apellido_materno,
        "contacto": contacto,
        "direccion": direccion,
    }
    for campo, valor in campos.items():
        limpio = valor.strip()
        if limpio == "":
            errors.append(f"ERROR en '{campo}': valor vacío (raw={valor!r})")
        else:
            rec[campo] = limpio
    if edad is not None:
        ok, edad_limpia, error = safe_int("edad", edad)
        if ok:
            rec["edad"] = edad_limpia
        else:
            errors.append(error)
    return rec


